#!/bin/sh
# SPDX-License-Identifier: LGPL-2.1-or-later
# Copyright (c) 2026 the MYIOSDECK author
#
# Spec 34 Part C5: the entry list of winevulkan's unix-call tables, from the enum of the given
# loader_thunks.h (Wine 11.4's dlls/winevulkan/loader_thunks.h, generated by make_vulkan).
#
#   gen-entries.sh <loader_thunks.h> <out.h>
#
# Writes WINEVULKAN_IOS_ENTRIES(X), one X(<index>, <name>) per enumerator of "enum unix_call" in
# order (unix_init is X(0, init)), and WINEVULKAN_IOS_ENTRY_COUNT. Fails unless every line between
# "{" and "unix_count," is a plain "unix_<name>," and unix_init comes first. Never writes into
# refs/.

set -eu
[ $# -eq 2 ] || { echo "usage: $0 <loader_thunks.h> <out.h>" >&2; exit 2; }
in=$1
out=$2
here=$(cd "$(dirname "$0")" && pwd)
refs=$(cd "$here/../../../refs" 2>/dev/null && pwd -P) || refs=""
parent=$(cd "$(dirname "$out")" && pwd -P) || { echo "$0: no directory for $out" >&2; exit 1; }
if [ -n "$refs" ]; then
    case "$parent/" in "$refs/"*) echo "$0: refusing to write into refs/: $out" >&2; exit 1 ;; esac
fi

awk '
    /^enum unix_call$/ { state = 1; next }
    state == 1 && /^[{]$/ { state = 2; next }
    state == 2 && /^[ \t]*unix_count,[ \t]*$/ { state = 3; exit }
    state == 2 {
        line = $0
        sub(/^[ \t]*/, "", line)
        if (line !~ /^unix_[A-Za-z0-9_]+,$/) { print "gen-entries.sh: unexpected line: " $0 > "/dev/stderr"; bad = 1; exit }
        sub(/,$/, "", line); sub(/^unix_/, "", line)
        names[n++] = line
    }
    END {
        if (bad || state != 3 || n == 0 || names[0] != "init") {
            if (!bad) print "gen-entries.sh: no enum unix_call ending in unix_count starting with unix_init" > "/dev/stderr"
            exit 1
        }
        print "/* generated by gen-entries.sh from loader_thunks.h; do not edit */"
        printf "#define WINEVULKAN_IOS_ENTRY_COUNT %d\n", n
        print "#define WINEVULKAN_IOS_ENTRIES(X) \\"
        for (i = 0; i < n; i++) printf "    X(%d, %s) \\\n", i, names[i]
        print "    /* end */"
    }
' "$in" > "$out.tmp"
mv "$out.tmp" "$out"
echo "gen-entries.sh: $(grep -c '^    X(' "$out") entries from $(basename "$in")"
